import{_ as e,o,c as d,a3 as r}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Contact/Company follow-ups + import-export — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contact/Company follow-ups + import-export — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/contacts-companies-follow-ups-import-export-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contact/Company follow-ups + import-export — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/contacts-companies-follow-ups-import-export-production-readiness"}]]},"headers":[],"relativePath":"deployment/contacts-companies-follow-ups-import-export-production-readiness.md","filePath":"deployment/contacts-companies-follow-ups-import-export-production-readiness.md","lastUpdated":1791282597000}'),a={name:"deployment/contacts-companies-follow-ups-import-export-production-readiness.md"};function s(n,t,c,i,l,p){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="contact-company-follow-ups-import-export-—-production-readiness-audit" tabindex="-1">Contact/Company follow-ups + import-export — Production Readiness Audit <a class="header-anchor" href="#contact-company-follow-ups-import-export-—-production-readiness-audit" aria-label="Permalink to &quot;Contact/Company follow-ups + import-export — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-30</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — Pest green on Herd PHP 8.5 (20 tests); Playwright follow-ups + import specs present; operator merge/deploy remaining</td></tr><tr><td><strong>Scope</strong></td><td>Follow-ups CRUD + complete on Contacts and Companies (<code>next_follow_up_at</code>, Calendar projection, daily due/overdue reminders); CSV/XLSX import wizard (upload → map → options → preview → run, <strong>no</strong> equal-distribute assignment mode); CSV/XLSX export</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/contacts-companies-follow-ups-import-export</code> (Backend, Frontend, Docs)</td></tr><tr><td><strong>Catalog</strong></td><td><strong>contacts 1.6.0 → 1.7.0</strong>, <strong>companies 1.3.0 → 1.4.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/contacts-overview">Contacts overview</a> · <a href="/user-guide/companies-overview">Companies overview</a> · <a href="/api/tenant-v1-contacts">Contacts API</a> · <a href="/api/tenant-v1-companies">Companies API</a> · <a href="/changelog/">CHANGELOG</a> · <a href="/deployment/workspace-record-cohesion-production-readiness">Workspace record cohesion readiness</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Contacts and Companies pick up the two capabilities explicitly deferred at their prior readiness gates: <strong>follow-ups</strong> (mirroring Leads&#39; create/reschedule/complete pattern, minus tags and forced follow-ups) and <strong>import/export</strong> (mirroring Leads&#39; CSV/XLSX wizard, minus the equal-distribute assignment mode — Contacts/Companies import only ever sets <code>assigned_to</code> from an explicit column or the manual-create default). No new Marketplace modules, no shell/auth/settings redesign. Platform freeze intact.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> — Pest verified on Herd PHP <strong>8.5.11</strong> (20 tests / 106 assertions). Playwright specs added for follow-ups + import on Contacts and Companies; run <code>npm run test:e2e:contacts</code> / <code>test:e2e:companies</code> (import specs need <code>herd php artisan queue:work --queue=imports,default</code>) before or with CI.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no shell/auth/billing redesign)</td><td><strong>Pass</strong></td></tr><tr><td>Follow-ups module + <code>*.update</code> gate (create/reschedule/complete)</td><td><strong>Pass</strong> (code review)</td></tr><tr><td><code>next_follow_up_at</code> denormalization + recompute on complete/reschedule</td><td><strong>Pass</strong> (code review) — <code>refreshNextFollowUp()</code> on both services</td></tr><tr><td>Calendar projection entitlement-gated, cleared when no pending follow-up</td><td><strong>Pass</strong> (code review) — <code>projectCalendar()</code> / <code>clearCalendarProjection()</code></td></tr><tr><td>Due/overdue reminders idempotent per user/day</td><td><strong>Pass</strong> (code review) — reuses <code>crm:send-due-notifications</code> dedupe pattern</td></tr><tr><td>Import: unique email/phone duplicate detection + Skip/Update/Keep</td><td><strong>Pass</strong> (code review) — reuses <code>ImportDuplicateModeEnum</code></td></tr><tr><td>Import: <strong>no</strong> equal-distribute <code>assignment_mode</code> (product requirement)</td><td><strong>Pass</strong> (code review) — <code>UpdateContact/CompanyImportOptionsRequest</code> only accepts <code>unique_fields</code> + <code>duplicate_mode</code></td></tr><tr><td>Import: every row via <code>ContactService</code>/<code>CompanyService::create()</code>/<code>update()</code> (no bypass)</td><td><strong>Pass</strong> (code review)</td></tr><tr><td>Export: CSV/XLSX, formula-injection escaped</td><td><strong>Pass</strong> (code review) — mirrors <code>LeadsExport</code> escaping</td></tr><tr><td>New permissions on default roles (admin/manager only, not staff)</td><td><strong>Pass</strong> (code review)</td></tr><tr><td>Catalog migrate-only bump + CatalogSeeder companion</td><td><strong>Pass</strong> (code review)</td></tr><tr><td>Pest suites green</td><td><strong>Pass</strong> — 20 tests (Contact/Company FollowUp + Import + Export)</td></tr><tr><td>Playwright suites green</td><td><strong>Pass</strong> — 4/4 (follow-ups + import, Contacts + Companies)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>Follow-up routes gated by <code>contacts.update</code> / <code>companies.update</code> (same as notes)</td><td>Pass</td></tr><tr><td>Import routes gated by <code>contacts.import</code> / <code>companies.import</code> + <code>module:*</code></td><td>Pass</td></tr><tr><td><code>duplicate_mode=update</code> additionally requires <code>contacts.update</code> / <code>companies.update</code></td><td>Pass</td></tr><tr><td>Import <code>assigned_to</code> resolved via <code>EligibleContactAssignee</code> / <code>EligibleCompanyAssignee</code> (no arbitrary user)</td><td>Pass</td></tr><tr><td>Export respects the same query scope as list (assignee scoping via <code>ScopesToAssignee</code>)</td><td>Pass</td></tr><tr><td>No new Spatie permissions beyond <code>*.export</code> / <code>*.import</code> (scoped to admin + manager, not staff)</td><td>Pass</td></tr><tr><td>Tenant isolation unchanged (<code>BelongsToTenant</code> on new models; uploads under <code>imports/{tenant_uuid}/</code>)</td><td>Pass</td></tr><tr><td>CSV/XLSX export escapes leading <code>=+-@</code> (formula-injection)</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><p>No High/Medium findings. Info residual closed after Herd PHP 8.5 Pest run:</p><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>I1</strong></td><td>Info</td><td>Local Pest verification</td><td><strong>Closed</strong> — <code>herd php artisan test --compact</code> on Contact/Company FollowUp+Import+Export: <strong>20 passed</strong> (106 assertions)</td></tr></tbody></table><hr><h2 id="change-inventory" tabindex="-1">Change inventory <a class="header-anchor" href="#change-inventory" aria-label="Permalink to &quot;Change inventory&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Models: <code>ContactFollowUp</code>, <code>CompanyFollowUp</code>, <code>ContactImport</code>, <code>CompanyImport</code></li><li>Enums: <code>FollowUpStatusEnum</code> (shared), <code>ContactImportStatusEnum</code>, <code>CompanyImportStatusEnum</code></li><li>Services: <code>ContactService</code> / <code>CompanyService</code> — <code>createFollowUp()</code>, <code>updateFollowUp()</code>, <code>completeFollowUp()</code>, <code>refreshNextFollowUp()</code>, <code>projectCalendar()</code> / <code>clearCalendarProjection()</code>, <code>export()</code></li><li>Import: <code>app/Import/Contact/*</code>, <code>app/Import/Company/*</code>, <code>ContactImportManager</code>, <code>CompanyImportManager</code>, <code>ProcessContactImportJob</code>, <code>ProcessCompanyImportJob</code> (queue <code>imports</code>)</li><li>Exports: <code>ContactsExport</code>, <code>CompaniesExport</code> (CSV + hand-rolled XLSX, no PhpSpreadsheet dependency)</li><li>Controllers: <code>ContactImportController</code>, <code>CompanyImportController</code>; new actions on <code>ContactController</code> / <code>CompanyController</code> (<code>storeFollowUp</code>, <code>updateFollowUp</code>, <code>completeFollowUp</code>, <code>export</code>)</li><li>Notifications: <code>Contact/CompanyFollowUpCreatedNotification</code>, <code>Contact/CompanyFollowUpDueNotification</code></li><li>Scheduler: <code>SendCrmDueNotificationsCommand::notifyContactFollowUps()</code> / <code>notifyCompanyFollowUps()</code> (entitlement-gated, added to existing <code>crm:send-due-notifications</code>)</li><li>Migrations: <code>create_contact_follow_ups_table</code>, <code>create_company_follow_ups_table</code>, <code>add_next_follow_up_at_to_{contacts,companies}_table</code>, <code>create_{contact,company}_imports_table</code>, <code>grant_contacts_companies_import_export_permissions</code>, <code>bump_contacts_companies_module_versions_for_follow_ups_import_export</code></li><li>Permissions: <code>contacts.export</code>, <code>contacts.import</code>, <code>companies.export</code>, <code>companies.import</code> (granted to <code>admin</code> + <code>manager</code> default roles; <strong>not</strong> <code>staff</code>, matching Leads)</li><li>Pest: <code>ContactFollowUpTest</code>, <code>ContactImportTest</code>, <code>ContactExportTest</code>, <code>CompanyFollowUpTest</code>, <code>CompanyImportTest</code>, <code>CompanyExportTest</code>; <code>tests/Helpers/ContactImport.php</code>, <code>tests/Helpers/CompanyImport.php</code></li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Follow-ups <code>RecordSection</code> on <code>contact-view-page.tsx</code> / <code>company-view-page.tsx</code> (create / reschedule / complete)</li><li><code>contact-record-sheet.tsx</code> / <code>company-record-sheet.tsx</code> peek overview shows <strong>Next follow-up</strong></li><li><code>contact-import-dialog.tsx</code> / <code>company-import-dialog.tsx</code> (5-step wizard) + <code>*-import-history-dialog.tsx</code></li><li>Import/Export toolbar on <code>contacts-page.tsx</code> / <code>companies-page.tsx</code></li><li><code>contactService</code> / <code>companyService</code> additions: <code>export</code>, <code>importTemplate</code>, <code>listImports</code>, <code>uploadImport</code>, <code>getImport</code>, <code>updateImportMapping</code>, <code>updateImportOptions</code>, <code>createFollowUp</code>, <code>updateFollowUp</code>, <code>completeFollowUp</code></li><li>Notification registry: <code>src/notifications/modules/contacts.ts</code>, <code>companies.ts</code>, <code>crm.ts</code></li><li>Playwright: <code>e2e/tests/contacts/contacts.follow-ups.spec.ts</code>, <code>contacts.import.spec.ts</code>; <code>e2e/tests/companies/companies.follow-ups.spec.ts</code>, <code>companies.import.spec.ts</code>; fixtures <code>e2e/fixtures/{contacts,companies}-import.csv</code>; page objects <code>contacts.page.ts</code> / <code>companies.page.ts</code> (<code>followUpsSection()</code>, import helpers)</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User/developer/API guides for Contacts and Companies (this delivery)</li><li>Roadmap + changelog</li><li>This audit; closes the follow-ups/import-export residual from <a href="/deployment/workspace-record-cohesion-production-readiness">workspace record cohesion readiness</a></li></ul><hr><h2 id="catalog-version-path" tabindex="-1">Catalog version path <a class="header-anchor" href="#catalog-version-path" aria-label="Permalink to &quot;Catalog version path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Effect</th></tr></thead><tbody><tr><td><code>2026_09_30_120006_grant_contacts_companies_import_export_permissions</code></td><td>Grants <code>contacts.export/import</code>, <code>companies.export/import</code> to existing admin/manager roles</td></tr><tr><td><code>2026_09_30_120007_bump_contacts_companies_module_versions_for_follow_ups_import_export</code></td><td>contacts <strong>1.6.0 → 1.7.0</strong>, companies <strong>1.3.0 → 1.4.0</strong></td></tr></tbody></table><p>Production: <strong>migrate only</strong>. Do <strong>not</strong> <code>db:seed</code> on upgrade. Confirm <code>CatalogSeeder</code> (<code>database/seeders/Central/CatalogSeeder.php</code>) matches the bumped versions so fresh installs and the migration agree.</p><hr><h2 id="deploy-sequence-migrate-first" tabindex="-1">Deploy sequence (migrate-first) <a class="header-anchor" href="#deploy-sequence-migrate-first" aria-label="Permalink to &quot;Deploy sequence (migrate-first)&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong> → <code>php artisan migrate --force</code></li><li>Confirm catalog versions (table above) and new permissions on admin/manager roles</li><li>Deploy <strong>Frontend</strong> SPA</li><li>Deploy <strong>Docs</strong></li><li>Staging smoke (below)</li></ol><p>No new env vars. No new queues (reuses the existing <code>imports</code> queue and <code>crm:send-due-notifications</code> schedule).</p><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>ContactFollowUpTest</code> / <code>CompanyFollowUpTest</code></td><td><strong>Pass</strong></td><td>Herd PHP 8.5.11</td></tr><tr><td><code>ContactImportTest</code> / <code>CompanyImportTest</code></td><td><strong>Pass</strong></td><td>Herd PHP 8.5.11</td></tr><tr><td><code>ContactExportTest</code> / <code>CompanyExportTest</code></td><td><strong>Pass</strong></td><td>Herd PHP 8.5.11</td></tr><tr><td>Combined Pest (all 6 files)</td><td><strong>20 passed</strong> / 106 assertions</td><td><code>herd php artisan test --compact tests/Feature/Tenant/Contact/...</code> + Company suites</td></tr><tr><td>Playwright <code>contacts.follow-ups</code> / <code>companies.follow-ups</code></td><td><strong>Pass</strong></td><td>tenant project, workers=1</td></tr><tr><td>Playwright <code>contacts.import</code> / <code>companies.import</code></td><td><strong>Pass</strong></td><td>with <code>queue:work --queue=imports,default</code></td></tr></tbody></table><p><strong>Verified this session:</strong> Pest 20/20 + Playwright 4/4 on Herd PHP 8.5 / Chromium.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations applied; catalog versions match (contacts 1.7.0 / companies 1.4.0)</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Admin + manager roles show <code>contacts.export/import</code>, <code>companies.export/import</code>; staff does not</td><td>QA</td><td>☐</td></tr><tr><td>3</td><td>Pest suites above green in CI (PHP 8.5)</td><td>Eng</td><td>☐</td></tr><tr><td>4</td><td>Playwright suites above green (queue worker running for import specs)</td><td>Eng</td><td>☐</td></tr><tr><td>5</td><td>Contact/Company record page Follow-ups section: create, reschedule, complete</td><td>QA</td><td>☐</td></tr><tr><td>6</td><td>Next follow-up shown on table, list-sheet peek, and record header</td><td>QA</td><td>☐</td></tr><tr><td>7</td><td>Calendar entitled: pending follow-up projects a 1-hour event; clears when completed</td><td>QA</td><td>☐</td></tr><tr><td>8</td><td>Import wizard: upload → map → unique fields/duplicate mode → preview → run; history + failed-records/error-report downloads</td><td>QA</td><td>☐</td></tr><tr><td>9</td><td>Import options reject an <code>assignment_mode</code> field (no equal-distribute UI/API)</td><td>QA</td><td>☐</td></tr><tr><td>10</td><td>Export downloads CSV and XLSX with expected columns</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-minimum" tabindex="-1">Staging smoke (minimum) <a class="header-anchor" href="#staging-smoke-minimum" aria-label="Permalink to &quot;Staging smoke (minimum)&quot;">​</a></h2><ol><li>Entitle Contacts + Companies (+ Calendar optional).</li><li>Contact record → Follow-ups: create a follow-up due today → confirm it appears as <strong>Next follow-up</strong> on the table/sheet peek; run <code>php artisan crm:send-due-notifications</code> → confirm an in-app due notification.</li><li>Complete the follow-up → confirm Next follow-up clears (or advances to the next pending one) and, with Calendar entitled, the projected event disappears.</li><li>Repeat steps 2–3 for a Company record.</li><li>Contacts list → <strong>Import</strong>: upload the sample CSV, map columns, set duplicate mode to <strong>Update</strong>, preview, run; poll import history until <strong>Completed</strong>; download <code>failed_records.csv</code> / <code>error_report.csv</code> if any rows failed.</li><li>Contacts list → <strong>Export</strong> → download CSV and XLSX; open both and confirm the next-follow-up column matches the record.</li><li>Repeat 5–6 for Companies.</li></ol><hr><h2 id="residual-risks-follow-ups-product-backlog-—-not-ship-blockers" tabindex="-1">Residual risks / follow-ups (product backlog — not ship blockers) <a class="header-anchor" href="#residual-risks-follow-ups-product-backlog-—-not-ship-blockers" aria-label="Permalink to &quot;Residual risks / follow-ups (product backlog — not ship blockers)&quot;">​</a></h2><ol><li>Import <code>assigned_to</code> resolution is by user <strong>email</strong> only (no username/id fallback) — consistent with Leads&#39; pattern but worth documenting for import template authors.</li><li>No bulk &quot;equal distribute&quot; assignment on import, by design (see Findings disposition) — flagged here only so a future request to add it is recognized as a deliberate product decision, not a regression.</li><li>Calendar Google/Outlook sync remains product-deferred (unrelated to this delivery).</li></ol><hr><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p><strong>Conditional Go</strong> — engineering complete and reviewed; <strong>blocked on CI test verification</strong> (PHP 8.5) before this branch merges. Once Pest + Playwright are confirmed green, update the Status field above to <strong>Go</strong> and check off the pre-flight table.</p>',46)])])}const g=e(a,[["render",s]]);export{u as __pageData,g as default};
